sys_script_include.script:
var PanoramaAdapter = Class.create();
PanoramaAdapter.prototype = Object.extendsObject(IFirewallAdapter, {
    initialize: function(params) {
		IFirewallAdapter.prototype.initialize.call(this, params);
        this.restMessageName = "PanoramaFirewallREST";
		this.schemaUtil = new SchemaUtil();
		this.logger = new PanoramaLogger("x_835786_firewall.PanoramaAdapter.debug", "PanoramaAdapter");
    },
    /**
     * Uses schema to make request based on predefined HTTP method; builds response body and then returns JSON
     * params:
     * @sysRestMessage (string) -- REST Message record name
     * @httpMethod (string) -- HTTP Method record name
     * @queryParams (object, optional) -- query params for endpoint passed into facade
     */
    fetchObjects: function(httpMethod, queryParams, schema) {
        var request = new sn_ws.RESTMessageV2(this.restMessageName, httpMethod);
        //apply query params if provided
        if (queryParams && typeof queryParams === "object") {
            for (var key in queryParams) {
                if (queryParams.hasOwnProperty(key)) {
                    request.setQueryParameter(key, queryParams[key]);
                }
            }
        }

        try {
            var response = request.execute();
            var status = response.getStatusCode();
            var body = response.getBody();

            if (status !== 200 && status !== 201) {
                var err = "REST call failed for endpoint: " + httpMethod + " Status: " + status;
				var inc = this.logger._createIncident(err, response);
				this.logger.debug("Created incident: " + inc);
                return {
                    success: false,
                    error: err
                };
            }

			var payload = JSON.parse(body);
			if(!payload) return {
				success: false,
				error: "There was an issue parsing the JSON string"
			};
			// var parsed = this._parseResponse(payload, schemaKey);
			// if(!parsed.success) return parsed;

            return {
                success: true,
                payload: payload
            };

        } catch (ex) {
            return {
                success: false,
                error: "Exception in fetch: " + ex.message
            };
        }

    },
	//push Panorama config objects to the Panorama interface
    pushObjects: function() {},
	//push user edits to objects to the Panorama interface
    editObject: function() {},
    //Get status of Panorama config commit job, if successful, proceed with local firewall commit
    getCommitJob: function() {},
    //XML CLI request to commit the rule to the firewall after commit job is successful
    commitToFirewall: function() {},


    type: "PanoramaAdapter"
});
